const $=s=>document.querySelector(s);async function call(path,body){const r=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(d.error||'Noe gikk galt.');return d}call('/api/gate').then(d=>{if(!d.required)return location.replace('/');$('#gate-question').firstChild.textContent=d.question;});$('#gate-form').onsubmit=async e=>{e.preventDefault();try{await call('/api/gate',{answer:$('#gate-answer').value});location.replace('/')}catch(e){$('#gate-error').textContent=e.message}};$('#gate-admin').onclick=()=>$('#gate-login').showModal();$('.close').onclick=()=>$('#gate-login').close();$('#gate-login-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;try{await call('/api/login',{username:f.username.value,password:f.password.value});location.replace('/')}catch(e){$('#gate-login-error').textContent=e.message}};
